3: public class Sample101 {
4:     public static void main(String[] args) throws Exception {
5:         if (args.length != 2) throw new IllegalArgumentException();
6:         String value = args[0];
7:         if (!value.matches("[A-Za-z0-9_]{1,32}")) return;
8:         value = args[1];
